from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], workers: int = 4) -> int:
    """Sum of square(x) for every x in xs, with the squares computed in
    parallel on a thread pool of `workers` threads.

    The result is exact (integer arithmetic) and identical for every
    worker count, since integer addition is order-independent. Returns 0
    for an empty list. Does not modify xs.
    """
    if not xs:
        return 0
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return sum(pool.map(square, xs))


def test_empty() -> None:
    assert sum_squares([]) == 0


def test_single() -> None:
    assert sum_squares([7]) == 49


def test_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_negatives_and_zero() -> None:
    assert sum_squares([-3, 0, 3]) == 18


def test_big_ints_exact() -> None:
    big = 10**30
    assert sum_squares([big, big]) == 2 * big * big


def test_default_matches_sequential() -> None:
    xs = list(range(-50, 50))
    assert sum_squares(xs) == sum(square(x) for x in xs)


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 64])
def test_same_at_every_worker_count(workers: int) -> None:
    xs = list(range(-200, 200))
    expected = sum(x * x for x in xs)
    assert sum_squares(xs, workers=workers) == expected


@pytest.mark.parametrize("workers", [1, 2, 16])
def test_more_workers_than_items(workers: int) -> None:
    assert sum_squares([2, 3], workers=workers) == 13
    assert sum_squares([], workers=workers) == 0


def test_input_not_modified() -> None:
    xs = [3, -1, 2]
    sum_squares(xs, workers=2)
    assert xs == [3, -1, 2]


def test_repeatable() -> None:
    xs = list(range(1000))
    results = {sum_squares(xs, workers=w) for w in (1, 2, 5, 8) for _ in range(3)}
    assert results == {sum(x * x for x in xs)}

